package com.jadhavr.erp.audit.service;
import com.jadhavr.erp.audit.entity.AuditLog; import com.jadhavr.erp.audit.enums.*; import com.jadhavr.erp.audit.repository.AuditLogRepository; import com.jadhavr.erp.auth.security.SecurityUtils; import com.jadhavr.erp.common.dto.PageResponse; import com.jadhavr.erp.user.entity.User; import com.jadhavr.erp.user.repository.UserRepository; import org.slf4j.*; import org.springframework.data.domain.*; import org.springframework.data.jpa.domain.Specification; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.*; import java.time.LocalDate; import java.util.*;
@Service public class AuditLogService {private static final Logger log=LoggerFactory.getLogger(AuditLogService.class);private final AuditLogRepository repo;private final UserRepository users;public AuditLogService(AuditLogRepository r,UserRepository u){repo=r;users=u;} @Transactional(propagation=Propagation.REQUIRES_NEW) public void log(AuditModule m,AuditAction a,String type,Long id,String description){try{User u=users.findById(SecurityUtils.getCurrentUserId()).orElse(null);logWithUser(u,m,a,type,id,description);}catch(Exception e){log.warn("Audit logging failed: {}",e.getMessage());}} @Transactional(propagation=Propagation.REQUIRES_NEW) public void logWithUser(User u,AuditModule m,AuditAction a,String type,Long id,String description){try{AuditLog x=new AuditLog();x.setActorUser(u);x.setActorName(u==null?"System":u.getFullName());x.setActorEmail(u==null?null:u.getEmail());x.setActorRoles(u==null?"SYSTEM":u.getRoles().stream().map(r->r.getName().name()).sorted().reduce((p,q)->p+","+q).orElse(""));x.setCollege(u==null?null:u.getCollege());x.setModule(m);x.setAction(a);x.setEntityType(type);x.setEntityId(id);x.setDescription(description);repo.save(x);}catch(Exception e){log.warn("Audit logging failed: {}",e.getMessage());}} @Transactional(readOnly=true) public PageResponse<AuditLog> search(String keyword,Long collegeId,AuditModule module,AuditAction action,Long actor,LocalDate from,LocalDate to,int page,int size){Long scope=SecurityUtils.isSuperAdmin()?collegeId:SecurityUtils.requireCurrentUser().getCollegeId();Specification<AuditLog>s=Specification.where(null);if(scope!=null)s=s.and((r,q,c)->c.equal(r.get("college").get("id"),scope));if(module!=null)s=s.and((r,q,c)->c.equal(r.get("module"),module));if(action!=null)s=s.and((r,q,c)->c.equal(r.get("action"),action));if(actor!=null)s=s.and((r,q,c)->c.equal(r.get("actorUser").get("id"),actor));if(from!=null)s=s.and((r,q,c)->c.greaterThanOrEqualTo(r.get("createdAt"),from.atStartOfDay()));if(to!=null)s=s.and((r,q,c)->c.lessThan(r.get("createdAt"),to.plusDays(1).atStartOfDay()));if(keyword!=null&&!keyword.isBlank()){String p="%"+keyword.toLowerCase()+"%";s=s.and((r,q,c)->c.or(c.like(c.lower(r.get("description")),p),c.like(c.lower(r.get("actorName")),p),c.like(c.lower(r.get("actorEmail")),p)));}return PageResponse.from(repo.findAll(s,PageRequest.of(page,Math.min(Math.max(size,1),100),Sort.by(Sort.Direction.DESC,"createdAt"))));}}
